<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Faturamento de tarefas';require APPPATH.'views/admin/companies/layout_head.php';$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'company_task_billing');
