<?php if(isset($profile['lines'])){ ?><h4>Linhas preservadas dos timers</h4><ul><?php foreach($profile['lines'] as $line){ ?><li>Timer #<?= (int)$line['timer_id']; ?> · <?= $esc($line['started_at'].' / '.$line['stopped_at']); ?> · <?= $esc($line['hours']); ?> h</li><?php } ?></ul><?php if($profile['excluded_zero_quantity_timer_ids']){ ?><p>Timers arredondados para 0.00 h: <?= $esc(implode(', ',$profile['excluded_zero_quantity_timer_ids'])); ?>. Preservados na origem e sem item na fatura.</p><?php }} ?><?php if($billing['stale']){ ?><p role="status">A origem mudou. Uma declaração pendente precisa de nova revisão.</p><?php } ?>
<?php require APPPATH.'views/admin/companies/billing_invoice_current.php'; ?>
<?php if($billing['state']==='converted'){ ?><p>Fatura emitida; tarefa e timers preservados.</p><a id="task-linked-invoice" href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.$billing['invoice_id'])); ?>">Abrir fatura vinculada</a><?php }elseif(in_array($billing['state'],['ready','converting'],true)){ ?><?= form_open($url);$hidden('convert'); ?><button id="task-billing-convert" type="submit"><?= $billing['state']==='converting'?'Retomar mesma emissão':'Emitir fatura da declaração'; ?></button><?= form_close(); ?><?php if($billing['state']==='ready'||$billing['can_release']){ ?><?= form_open($url);$hidden('disable'); ?><button type="submit">Retirar declaração sem apagar histórico</button><?= form_close(); ?><?php }} ?><?php } ?>
<?php if(!$billing&&in_array(($task['billing_state']??null),['converting','converted'],true)){ ?><p>O projeto inteiro está reservado ou faturado por preço fixo. Tarefa e timers preservados.</p><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_project_fixed_billing?project='.(int)$task['project_id'])); ?>">Consultar faturamento fixo do projeto</a><?php } ?>
