<?php if($task['status']==='done'&&!in_array(($task['billing_state']??null),['converting','converted'],true)&&(!$billing||in_array($billing['state'],['ready','disabled'],true))){ ?><h3>Revisar faturamento por hora</h3><?= form_open($url);$hidden('prepare'); ?><label>Moeda<select id="task-billing-currency" name="billing[currency]" required><?php foreach($currencies as $currency){ ?><option value="<?= (int)$currency['id']; ?>"><?= $esc($currency['name']); ?></option><?php } ?></select></label><label>Emissão<input id="task-billing-date" type="date" name="billing[date]" value="<?= $esc(gmdate('Y-m-d')); ?>" required></label><label>Vencimento<input id="task-billing-due" type="date" name="billing[due_date]" value="<?= $esc(gmdate('Y-m-d')); ?>" required></label><label>Linhas da fatura<select id="task-billing-lines" name="billing[line_mode]"><option value="task_per_item">Um item para a tarefa</option><option value="timesheets_individually">Uma linha por timer encerrado</option></select></label><label>Taxa por hora<input id="task-billing-rate" name="billing[rate]" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" required></label><label>Arredondamento<select id="task-billing-round" name="billing[round_mode]"><option value="none">Sem intervalo</option><option value="up">Para cima</option><option value="down">Para baixo</option><option value="nearest">Mais próximo; empate para cima</option></select></label><label>Intervalo em minutos<select id="task-billing-minutes" name="billing[round_minutes]"><?php foreach([0,5,10,15,20,25,30,35,40,45] as $minutes){ ?><option value="<?= $minutes; ?>"><?= $minutes===0?'0 (sem intervalo)':$minutes; ?></option><?php } ?></select></label><p>Sem intervalo exige 0; outros modos exigem um intervalo entre 5 e 45 minutos. A quantidade de horas sempre tem duas casas.</p>
